<?php

declare(strict_types=1);

namespace App\Policies;

use Illuminate\Foundation\Auth\User as AuthUser;

/**
 * Generated by Shield. These abilities belong to admins managing end users
 * in the panel; an end user holds none of them.
 */
final class UserPolicy
{
    public function viewAny(AuthUser $actor): bool
    {
        return $actor->can('view_any:user');
    }

    public function view(AuthUser $actor): bool
    {
        return $actor->can('view:user');
    }

    public function create(AuthUser $actor): bool
    {
        return $actor->can('create:user');
    }

    public function update(AuthUser $actor): bool
    {
        return $actor->can('update:user');
    }

    public function delete(AuthUser $actor): bool
    {
        return $actor->can('delete:user');
    }

    public function deleteAny(AuthUser $actor): bool
    {
        return $actor->can('delete_any:user');
    }
}
